-- Add the derived column (nullable initially)
ALTER TABLE orders ADD COLUMN amount_cents bigint;

-- Trigger function to maintain amount_cents from amount
CREATE OR REPLACE FUNCTION orders_set_amount_cents() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW.amount_cents := (NEW.amount * 100)::bigint;
    RETURN NEW;
END;
$$;

-- Attach trigger before backfill so new/updated rows are covered immediately
CREATE TRIGGER orders_set_amount_cents_trg
BEFORE INSERT OR UPDATE ON orders
FOR EACH ROW EXECUTE FUNCTION orders_set_amount_cents();

-- Procedure to backfill existing rows in small batches with SKIP LOCKED
CREATE PROCEDURE backfill_amount_cents() LANGUAGE plpgsql AS $$
DECLARE
    batch_size int := 2000;
    rows_updated int;
BEGIN
    LOOP
        -- Disable triggers for this batch to avoid double work
        SET LOCAL session_replication_role = replica;
        WITH to_update AS (
            SELECT id
            FROM orders
            WHERE amount_cents IS NULL
            ORDER BY id
            LIMIT batch_size
            FOR UPDATE SKIP LOCKED
        )
        UPDATE orders o
        SET amount_cents = (o.amount * 100)::bigint
        FROM to_update tu
        WHERE o.id = tu.id;
        GET DIAGNOSTICS rows_updated = ROW_COUNT;
        COMMIT;
        EXIT WHEN rows_updated = 0;
        PERFORM pg_sleep(0.005);
    END LOOP;
END;
$$;

-- Run the backfill
CALL backfill_amount_cents();

-- Clean up
DROP PROCEDURE backfill_amount_cents();

-- Enforce NOT NULL now that all rows have a value
ALTER TABLE orders ALTER COLUMN amount_cents SET NOT NULL;
```

